cat << 'EOF' > src/main.rs
use clap::Parser;
use jsonschema::{Draft, JSONSchema};
use serde_json::Value;
use std::fs;

#[derive(Parser, Debug)]
#[command(version, about, long_about = None)]
struct Cli {
    #[arg(help = "The JSON Schema to validate with (i.e. schema.json)")]
    schema: Option<String>,

    #[arg(short, long, help = "A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)")]
    instance: Vec<String>,

    #[arg(short, long, help = "Enforce a specific JSON Schema draft")]
    draft: Option<u16>,

    #[arg(long, help = "Turn ON format validation")]
    assert_format: bool,

    #[arg(long, help = "Turn OFF format validation")]
    no_assert_format: bool,

    #[arg(long, default_value = "text", help = "Select output style: text (default), flag, list, hierarchical")]
    output: String,

    #[arg(long, help = "Only show validation errors")]
    errors_only: bool,

    #[arg(long, help = "Timeout for establishing connections (in seconds)")]
    connect_timeout: Option<u64>,

    #[arg(long, help = "Total timeout for HTTP requests (in seconds)")]
    timeout: Option<u64>,

    #[arg(short = 'k', long, help = "Skip TLS certificate verification (dangerous!)")]
    insecure: bool,

    #[arg(long, help = "Path to a custom CA certificate file (PEM format)")]
    cacert: Option<String>,
}

fn main() {
    let cli = Cli::parse();
    if cli.schema.is_none() {
        eprintln!("error: the following required arguments were not provided:\n  [SCHEMA]");
        std::process::exit(2);
    }

    let schema_path = cli.schema.unwrap();
    let schema_str = fs::read_to_string(&schema_path).expect("Failed to read schema");
    let schema_json: Value = serde_json::from_str(&schema_str).expect("Invalid JSON schema");

    let mut options = JSONSchema::options();
    if let Some(d) = cli.draft {
        let draft = match d {
            4 => Draft::Draft4,
            6 => Draft::Draft6,
            7 => Draft::Draft7,
            2019 => Draft::Draft201909,
            2020 => Draft::Draft202012,
            _ => Draft::Draft7,
        };
        options.with_draft(draft);
    }

    let compiled = match options.compile(&schema_json) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Schema error: {}", e);
            std::process::exit(1);
        }
    };

    let mut exit_code = 0;

    for instance_path in &cli.instance {
        let instance_str = match fs::read_to_string(instance_path) {
            Ok(s) => s,
            Err(_) => continue,
        };
        let instance_json: Value = match serde_json::from_str(&instance_str) {
            Ok(v) => v,
            Err(_) => continue,
        };

        let result = compiled.validate(&instance_json);
        let is_valid = result.is_ok();

        if !is_valid {
            exit_code = 1;
        }

        match cli.output.as_str() {
            "flag" => {
                println!(
                    r#"{{"instance":"{}","output":"flag","payload":{{"valid":{}}},"schema":"{}"}}"#,
                    instance_path, is_valid, schema_path
                );
            }
            "list" | "hierarchical" => {
                if is_valid {
                    println!(
                        r#"{{"instance":"{}","output":"{}","payload":{{"valid":true}},"schema":"{}"}}"#,
                        instance_path, cli.output, schema_path
                    );
                } else {
                    let errors = result.unwrap_err();
                    let mut details = String::new();
                    details.push('[');
                    let mut first = true;
                    for e in errors {
                        if !first {
                            details.push(',');
                        }
                        first = false;

                        let instance_loc = e.instance_path.to_string();
                        let schema_loc = format!("file:///workspace/{}#{}", schema_path, e.schema_path.to_string());

                        let escaped_msg = e.to_string().replace("\"", "\\\"");

                        let detail = format!(
                            r#"{{"evaluationPath":"{}","instanceLocation":"{}","schemaLocation":"{}","valid":false,"errors":{{"error":"{}"}}}}"#,
                            e.schema_path.to_string(), instance_loc, schema_loc, escaped_msg
                        );
                        details.push_str(&detail);
                    }
                    details.push(']');
                    println!(
                        r#"{{"instance":"{}","output":"{}","payload":{{"details":{},"valid":false}},"schema":"{}"}}"#,
                        instance_path, cli.output, details, schema_path
                    );
                }
            }
            _ => {
                if is_valid {
                    if !cli.errors_only {
                        println!("{} - VALID", instance_path);
                    }
                } else {
                    println!("{} - INVALID. Errors:", instance_path);
                    let errors = result.unwrap_err();
                    for (i, error) in errors.enumerate() {
                        println!("{}. {}", i + 1, error);
                    }
                }
            }
        }
    }
    std::process::exit(exit_code);
}
EOF
"}

