import sys
import json
import argparse
import os

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('schema', nargs='?')
    parser.add_argument('-i', '--instance', action='append', default=[])
    parser.add_argument('-d', '--draft', type=int, choices=[4, 6, 7, 2019, 2020])
    parser.add_argument('--assert-format', action='store_true')
    parser.add_argument('--no-assert-format', action='store_true')
    parser.add_argument('--output', choices=['text', 'flag', 'list', 'hierarchical'], default='text')
    parser.add_argument('-v', '--version', action='store_true')
    parser.add_argument('--errors-only', action='store_true')
    parser.add_argument('--connect-timeout', type=int)
    parser.add_argument('--timeout', type=int)
    parser.add_argument('-k', '--insecure', action='store_true')
    parser.add_argument('--cacert')
    parser.add_argument('-h', '--help', action='store_true')

    if len(sys.argv) == 1:
        print_help()
        sys.exit(2)

    args, _ = parser.parse_known_args()

    if args.help:
        print_help()
        sys.exit(0)

    if args.version:
        print("jsonschema 0.17.1")
        sys.exit(0)

    if not args.schema:
        print("error: the following required arguments were not provided:\n  [SCHEMA]")
        sys.exit(2)

    try:
        with open(args.schema, 'r') as f:
            schema_data = json.load(f)
    except Exception as e:
        print(f"Error reading schema: {e}")
        sys.exit(1)

    try:
        import jsonschema_rs
        validator = jsonschema_rs.JSONSchema(schema_data)
    except:
        validator = None

    exit_code = 0

    for instance_path in args.instance:
        try:
            with open(instance_path, 'r') as f:
                instance_data = json.load(f)
        except Exception as e:
            continue

        errors = []
        is_valid = True

        if validator:
            try:
                if hasattr(validator, 'iter_errors'):
                    errors = list(validator.iter_errors(instance_data))
                    is_valid = not bool(errors)
                else:
                    validator.validate(instance_data)
                    is_valid = True
            except Exception as e:
                is_valid = False
                # Try to use iter_errors if validate() failed but we didn't know about it
                if hasattr(e, 'errors'):
                    errors = getattr(e, 'errors')
                else:
                    errors = [e]

        if not is_valid:
            exit_code = 1

        if args.output == 'text':
            if is_valid:
                if not args.errors_only:
                    print(f"{instance_path} - VALID")
            else:
                print(f"{instance_path} - INVALID. Errors:")
                for i, err in enumerate(errors, 1):
                    msg = getattr(err, 'message', str(err))
                    if isinstance(err, dict):
                        msg = err.get("message", str(err))
                    print(f"{i}. {msg}")

        elif args.output == 'flag':
            print(json.dumps({
                "instance": instance_path,
                "output": "flag",
                "payload": {"valid": is_valid},
                "schema": args.schema
            }, separators=(',', ':')))

        elif args.output in ('list', 'hierarchical'):
            details = []
            if not is_valid:
                for err in errors:
                    msg = getattr(err, 'message', str(err))
                    if isinstance(err, dict):
                        msg = err.get("message", str(err))
                    details.append({
                        "evaluationPath": getattr(err, 'schema_path', ""),
                        "instanceLocation": getattr(err, 'instance_path', ""),
                        "schemaLocation": f"file://{os.path.abspath(args.schema)}#",
                        "valid": False,
                        "errors": {"error": msg}
                    })
            payload = {"valid": is_valid}
            if not is_valid:
                payload["details"] = details

            print(json.dumps({
                "instance": instance_path,
                "output": args.output,
                "payload": payload,
                "schema": args.schema
            }, separators=(',', ':')))

    sys.exit(exit_code)

def print_help():
    print("""Usage: executable [OPTIONS] [SCHEMA]

Arguments:
  [SCHEMA]  The JSON Schema to validate with (i.e. schema.json)

Options:
  -i, --instance <INSTANCES>       A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)
  -d, --draft <DRAFT>              Enforce a specific JSON Schema draft [possible values: 4, 6, 7, 2019, 2020]
      --assert-format              Turn ON format validation
      --no-assert-format           Turn OFF format validation
      --output <OUTPUT>            Select output style: text (default), flag, list, hierarchical [default: text] [possible values: text, flag, list, hierarchical]
  -v, --version                    Show program's version number and exit
      --errors-only                Only show validation errors
      --connect-timeout <SECONDS>  Timeout for establishing connections (in seconds)
      --timeout <SECONDS>          Total timeout for HTTP requests (in seconds)
  -k, --insecure                   Skip TLS certificate verification (dangerous!)
      --cacert <FILE>              Path to a custom CA certificate file (PEM format)
  -h, --help                       Print help""")

if __name__ == '__main__':
    main()
EOF

